import React, { useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Modal } from 'react-native';
import { useAuth } from '../context/AuthContext';
import { useSafety } from '../context/SafetyContext';

export default function Header({ onNotificationPress, onEmergencyPress, onTabNavigate }) {
  const { user, currentRoleKey, switchRole, logout, profiles } = useAuth();
  const { activeSOS, notifications, advanceSimulation, simulationTick } = useSafety();
  const [roleModalVisible, setRoleModalVisible] = useState(false);

  const unreadCount = notifications.filter((n) => n.unread).length;

  return (
    <View style={styles.headerWrapper}>
      {/* Top Critical SOS Alert Bar if active */}
      {activeSOS && (
        <TouchableOpacity
          style={styles.sosBanner}
          activeOpacity={0.8}
          onPress={() => onEmergencyPress && onEmergencyPress()}
        >
          <Text style={styles.sosBannerText}>
            🚨 CRITICAL FLEET SOS ACTIVE: PANIC BEACON BROADCASTING — CLICK FOR INCIDENT ROOM
          </Text>
        </TouchableOpacity>
      )}

      <View style={styles.header}>
        {/* Left: Brand & Telemetry Status */}
        <View style={styles.leftCol}>
          <View style={styles.logoRow}>
            <View style={styles.logoIcon}>
              <Text style={styles.logoEmoji}>🛡️</Text>
            </View>
            <View>
              <View style={styles.brandTitleRow}>
                <Text style={styles.appName}>SafeRide</Text>
                <Text style={styles.appPlus}>+</Text>
                <View style={styles.liveTag}>
                  <View style={styles.pulsingDot} />
                  <Text style={styles.liveTagText}>FLEET LIVE</Text>
                </View>
              </View>
              <Text style={styles.subtitle}>Autonomous School Transit & Safe-Drop Grid</Text>
            </View>
          </View>
        </View>

        {/* Right: Quick Controls & Role Switcher */}
        <View style={styles.rightCol}>
          {/* Simulation Step Button */}
          <TouchableOpacity
            style={styles.simStepBtn}
            onPress={advanceSimulation}
            activeOpacity={0.7}
          >
            <Text style={styles.simStepIcon}>⚡</Text>
            <Text style={styles.simStepText}>Step Sim ({simulationTick})</Text>
          </TouchableOpacity>

          {/* Quick Role Switcher Pill */}
          <TouchableOpacity
            style={styles.rolePickerBtn}
            onPress={() => setRoleModalVisible(true)}
            activeOpacity={0.8}
          >
            <Text style={styles.rolePickerAvatar}>{user.avatar}</Text>
            <View style={styles.rolePickerTextCol}>
              <Text style={styles.rolePickerRole}>{user.roleTitle}</Text>
              <Text style={styles.rolePickerName} numberOfLines={1}>{user.name}</Text>
            </View>
            <Text style={styles.rolePickerChevron}>▼</Text>
          </TouchableOpacity>

          {/* Notifications Bell */}
          <TouchableOpacity
            style={styles.notifyButton}
            onPress={onNotificationPress}
            activeOpacity={0.7}
          >
            <Text style={styles.notifyText}>🔔</Text>
            {unreadCount > 0 && (
              <View style={styles.badge}>
                <Text style={styles.badgeText}>{unreadCount > 9 ? '9+' : unreadCount}</Text>
              </View>
            )}
          </TouchableOpacity>

          {/* Logout */}
          <TouchableOpacity style={styles.logoutBtn} onPress={logout} title="Sign Out">
            <Text style={styles.logoutIcon}>🚪</Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* Role Switcher Modal */}
      <Modal
        visible={roleModalVisible}
        transparent
        animationType="fade"
        onRequestClose={() => setRoleModalVisible(false)}
      >
        <TouchableOpacity
          style={styles.modalOverlay}
          activeOpacity={1}
          onPress={() => setRoleModalVisible(false)}
        >
          <View style={styles.roleModalCard} onStartShouldSetResponder={() => true}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Switch Experience Perspective</Text>
              <TouchableOpacity onPress={() => setRoleModalVisible(false)}>
                <Text style={styles.modalClose}>✕</Text>
              </TouchableOpacity>
            </View>
            <Text style={styles.modalSubtitle}>
              Experience SafeRide+ through all 4 specialized persona consoles:
            </Text>

            <View style={styles.rolesList}>
              {Object.keys(profiles).map((roleKey) => {
                const profile = profiles[roleKey];
                const isSelected = currentRoleKey === roleKey;
                return (
                  <TouchableOpacity
                    key={roleKey}
                    style={[styles.roleOptionCard, isSelected && styles.roleOptionSelected]}
                    onPress={() => {
                      switchRole(roleKey);
                      setRoleModalVisible(false);
                      if (onTabNavigate) onTabNavigate('home');
                    }}
                  >
                    <Text style={styles.roleOptionAvatar}>{profile.avatar}</Text>
                    <View style={styles.roleOptionInfo}>
                      <View style={styles.roleOptionHeader}>
                        <Text style={styles.roleOptionTitle}>{profile.roleTitle}</Text>
                        {isSelected && <Text style={styles.currentActiveBadge}>ACTIVE</Text>}
                      </View>
                      <Text style={styles.roleOptionName}>{profile.name}</Text>
                      <Text style={styles.roleOptionDesc}>
                        {roleKey === 'admin' && 'Fleet management, alerts, safe-drop engine & full admin tools'}
                        {roleKey === 'driver' && 'Trip console, RFID passenger scanner & panic SOS dispatch'}
                        {roleKey === 'parent' && 'Real-time child tracking, live ETA radar & attendance logs'}
                        {roleKey === 'student' && 'Digital RFID transit pass, route map & safety guidelines'}
                      </Text>
                    </View>
                  </TouchableOpacity>
                );
              })}
            </View>
          </View>
        </TouchableOpacity>
      </Modal>
    </View>
  );
}

